INSERT INTO process_definitions (definition_id, workspace_id, name, version, source_hash, payload, router_time, time_basis, origin_installation, origin_machine, import_digest) VALUES (json_extract(?1, '$.record.envelope.id'), json_extract(?1, '$.record.envelope.scope.workspace'), json_extract(?1, '$.record.reference.name'), json_extract(?1, '$.record.reference.version'), json_extract(?1, '$.record.reference.sourceHash'), ?1, ?2, ?3, ?4, ?5, ?6) ON CONFLICT(definition_id) DO UPDATE SET workspace_id = excluded.workspace_id, name = excluded.name, version = excluded.version, source_hash = excluded.source_hash, payload = excluded.payload, router_time = excluded.router_time, time_basis = excluded.time_basis, origin_installation = excluded.origin_installation, origin_machine = excluded.origin_machine, import_digest = coalesce(process_definitions.import_digest, excluded.import_digest);
